public class MutableDateTime_addDays_TriageGen0Test {

    @Test
    public void testAddDays_WithPositiveDays() {
        // Test adding more than 1 day
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        dt.addDays(5);
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(6, dt.getDayOfMonth());
    }

    @Test
    public void testAddDays_WithNegativeDays() {
        // Test adding negative days
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 12, 0, 0, 0);
        dt.addDays(-3);
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(7, dt.getDayOfMonth());
    }

    @Test
    public void testAddDays_WithZeroDays() {
        // Test adding 0 days (branch: days != 1)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();
        dt.addDays(0);
        assertEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_WithOneDay() {
        // Test adding exactly 1 day (branch: days != 1 is false, so no operation performed)
        // This tests the specific optimization/logic in the provided code snippet
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();
        dt.addDays(1);
        assertEquals("When days is 1, the method should not change the millis (based on the provided code logic)", 
                     originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_CrossingMonthBoundary() {
        // Test adding days that cross a month boundary
        MutableDateTime dt = new MutableDateTime(2023, 1, 30, 12, 0, 0, 0);
        dt.addDays(3);
        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(2, dt.getDayOfMonth());
    }

    @Test
    public void testAddDays_CrossingYearBoundary() {
        // Test adding days that cross a year boundary
        MutableDateTime dt = new MutableDateTime(2022, 12, 31, 12, 0, 0, 0);
        dt.addDays(2);
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(2, dt.getDayOfMonth());
    }

    @Test
    public void testAddDays_LeapYear() {
        // Test leap year handling
        MutableDateTime dt = new MutableDateTime(2024, 2, 28, 12, 0, 0, 0);
        dt.addDays(2);
        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());
    }
}
